var i=`principle-of-least-privilege`;var s=72;var r={en:[{id:`T072-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Principle of Least Privilege`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Zero Trust treats network location as insufficient proof of trust and requires explicit identity, device/workload context and policy for access decisions.`},{id:`B`,text:`Cryptography protects information and proves authenticity using well-studied primitives: symmetric encryption, public-key cryptography, cryptographic hashes, MACs and digital signatures.`},{id:`C`,text:`Least privilege gives identities and processes only the permissions necessary for their assigned tasks, ideally for the shortest required period.`},{id:`D`,text:`Defense in Depth uses multiple independent security controls so a single error or compromise does not expose the entire system.`}]},{id:`T072-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Principle of Least Privilege`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Draw data flows, actors, trust boundaries and stores.`},{id:`B`,text:`Authenticate and authorize every meaningful access path, segment resources and continuously evaluate risk signals.`},{id:`C`,text:`Scope access by resource, action, tenant and environment.`},{id:`D`,text:`Prefer secret managers and short-lived workload identities, restrict access by environment, avoid logs and repository commits, and plan emergency rotation.`}]},{id:`T072-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A reporting worker needs read-only access to selected analytics views, not permission to delete guest records or read payment tokens.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`CI deployment credentials should not be shared with runtime services.`},{id:`B`,text:`A payment API key is stored in a controlled secret service, injected only into the server runtime and rotated with overlap so live requests are not interrupted.`},{id:`C`,text:`An API signs webhook messages with a keyed MAC so recipients detect tampering, while passwords are stored using Argon2id or another appropriate password hashing function, never reversible encryption.`},{id:`D`,text:`None alone should be assumed perfect.`}]},{id:`T072-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Principle of Least Privilege`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`An absence of known CVEs does not prove a package safe; typosquatting and maintainer compromise are different threats.`},{id:`B`,text:`Zero Trust does not mean reauthenticating human users on every click.`},{id:`C`,text:`Hashing is not encryption; Base64 is not security.`},{id:`D`,text:`Overly granular policies can become unmanageable; ownership and automation matter.`}]},{id:`T072-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It limits the blast radius of compromise and mistakes.`}]}]},{id:`T072-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`A service should receive administrator permissions to avoid future access errors.`}]}]},{id:`T072-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Never accept broad production-admin permissions merely to bypass an inconvenient integration test.`}]}]},{id:`T072-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Principle of Least Privilege`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Least privilege should give permanent access for temporary maintenance tasks.`},{id:`B`,text:`Base64 encoding protects sensitive information like encryption does.`},{id:`C`,text:`Least privilege gives identities and processes only the permissions necessary for their assigned tasks, ideally for the shortest required period.`},{id:`D`,text:`Scope access by resource, action, tenant and environment.`}]},{id:`T072-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Principle of Least Privilege`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Never accept broad production-admin permissions merely to bypass an inconvenient integration test.`},{id:`B`,text:`Any request from a private subnet should bypass authentication in Zero Trust.`},{id:`C`,text:`A service should receive administrator permissions to avoid future access errors.`},{id:`D`,text:`CI deployment credentials should not be shared with runtime services.`}]},{id:`T072-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A reporting worker needs read-only access to selected analytics views, not permission to delete guest records or read payment tokens.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to audit a package update PR, explain provenance, lockfile changes, install scripts, CI permissions and a safe rollout path.`},{id:`B`,text:`Have an agent draft permissions for API, worker, CI and operator roles, then test denied access for every unnecessary resource and action.`},{id:`C`,text:`Ask an agent to propose a webhook signature and password-storage design using standard libraries. Require a threat discussion, test vectors and key-rotation plan.`},{id:`D`,text:`Ask an agent to map trust boundaries across frontend, API, worker and database. Require a policy enforcement point and failure behavior for missing identity claims.`}]},{id:`T072-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`What evidence justifies every permission held by a production service account?`}]}]},{id:`T072-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A reporting worker needs read-only access to selected analytics views, not permission to delete guest records or read payment tokens.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Principle of Least Privilege`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T072-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A reporting worker needs read-only access to selected analytics views, not permission to delete guest records or read payment tokens.`,b:!0},{t:` — propose three checks for `},{t:`Principle of Least Privilege`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T072-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A reporting worker needs read-only access to selected analytics views, not permission to delete guest records or read payment tokens.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T072-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Principle of Least Privilege`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A reporting worker needs read-only access to selected analytics views, not permission to delete guest records or read payment tokens.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T072-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Принцип найменших привілеїв`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Zero Trust не вважає розташування в мережі достатнім доказом довіри й вимагає ідентичності, контексту пристрою/навантаження та політики доступу.`},{id:`B`,text:`Криптографія захищає дані та підтверджує автентичність через вивчені примітиви: симетричне й асиметричне шифрування, хеші, MAC та цифрові підписи.`},{id:`C`,text:`Принцип найменших привілеїв надає особам і процесам тільки необхідні права та, бажано, на мінімально потрібний час.`},{id:`D`,text:`Багаторівневий захист застосовує кілька незалежних контролів, щоб одна помилка чи злам не відкривали всю систему.`}]},{id:`T072-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Принцип найменших привілеїв`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Намалюйте потоки даних, учасників, межі довіри й сховища.`},{id:`B`,text:`Автентифікуйте й авторизуйте кожен значущий доступ, сегментуйте ресурси та переоцінюйте ризики.`},{id:`C`,text:`Обмежуйте доступ за ресурсом, дією, tenant і середовищем.`},{id:`D`,text:`Використовуйте secret manager і короткоживучі workload identities, розмежовуйте середовища, не допускайте секретів у логах і Git та плануйте термінову ротацію.`}]},{id:`T072-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Воркер звітності має читати лише дозволені аналітичні view, а не видаляти гостей чи читати платіжні токени.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Облікові дані CI для деплою не повинні використовуватися runtime-сервісами.`},{id:`B`,text:`Ключ платіжного API зберігається в контрольованому сервісі секретів, доступний лише серверному runtime і змінюється з перехідним періодом без обриву запитів.`},{id:`C`,text:`API підписує webhook через keyed MAC для виявлення змін, а паролі зберігає через Argon2id чи інший придатний password hashing, а не зворотне шифрування.`},{id:`D`,text:`Жоден із шарів не вважається бездоганним.`}]},{id:`T072-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Принцип найменших привілеїв`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Відсутність відомих CVE не доводить безпеку пакета; typosquatting і захоплення акаунта maintainer — інші загрози.`},{id:`B`,text:`Zero Trust не означає повторний логін людини після кожного кліку.`},{id:`C`,text:`Хешування не є шифруванням, а Base64 — не захист.`},{id:`D`,text:`Надмірно дрібні політики важко супроводжувати; потрібні власники й автоматизація.`}]},{id:`T072-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Це зменшує наслідки злому й помилки.`}]}]},{id:`T072-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Сервісу слід одразу давати права адміністратора, щоб уникнути помилок доступу.`}]}]},{id:`T072-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Не надавайте production-admin права лише заради проходження незручного інтеграційного тесту.`}]}]},{id:`T072-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Принцип найменших привілеїв`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Найменші привілеї означають постійний доступ для тимчасових робіт.`},{id:`B`,text:`Кодування Base64 захищає секретні дані так само, як шифрування.`},{id:`C`,text:`Принцип найменших привілеїв надає особам і процесам тільки необхідні права та, бажано, на мінімально потрібний час.`},{id:`D`,text:`Обмежуйте доступ за ресурсом, дією, tenant і середовищем.`}]},{id:`T072-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Принцип найменших привілеїв`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Не надавайте production-admin права лише заради проходження незручного інтеграційного тесту.`},{id:`B`,text:`Будь-який запит із приватної підмережі має обходити автентифікацію в Zero Trust.`},{id:`C`,text:`Сервісу слід одразу давати права адміністратора, щоб уникнути помилок доступу.`},{id:`D`,text:`Облікові дані CI для деплою не повинні використовуватися runtime-сервісами.`}]},{id:`T072-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Воркер звітності має читати лише дозволені аналітичні view, а не видаляти гостей чи читати платіжні токени.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента перевірити PR з оновленням пакетів: походження, зміни lockfile, install scripts, права CI й безпечний rollout.`},{id:`B`,text:`Попросіть агента описати права API, воркера, CI та оператора й протестувати відмову для кожного непотрібного ресурсу й дії.`},{id:`C`,text:`Попросіть агента спроєктувати підпис webhook і зберігання паролів стандартними бібліотеками. Вимагайте аналіз загроз, тестові вектори та ротацію ключів.`},{id:`D`,text:`Попросіть агента намалювати межі довіри між фронтендом, API, воркером та БД. Вимагайте точки застосування політики й поведінку за відсутніх identity claims.`}]},{id:`T072-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Чим обґрунтовано кожен дозвіл production service account?`}]}]},{id:`T072-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Воркер звітності має читати лише дозволені аналітичні view, а не видаляти гостей чи читати платіжні токени.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Принцип найменших привілеїв`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T072-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Воркер звітності має читати лише дозволені аналітичні view, а не видаляти гостей чи читати платіжні токени.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Принцип найменших привілеїв`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T072-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Воркер звітності має читати лише дозволені аналітичні view, а не видаляти гостей чи читати платіжні токени.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T072-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Принцип найменших привілеїв`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Воркер звітності має читати лише дозволені аналітичні view, а не видаляти гостей чи читати платіжні токени.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var o={slug:i,topicId:72,questions:r};export{o as default,r as questions,i as slug,s as topicId};